CREATE TABLE `industry_list_items` (`id` INT NOT NULL AUTO_INCREMENT, `industry_id` INT NOT NULL, `section` VARCHAR(40) NOT NULL, `text` VARCHAR(300) NOT NULL, `sort_order` INT NOT NULL DEFAULT 0, PRIMARY KEY (`id`), INDEX `industry_list_items_industry_id_section_sort_order_idx` (`industry_id`, `section`, `sort_order`), CONSTRAINT `industry_list_items_industry_id_fkey` FOREIGN KEY (`industry_id`) REFERENCES `industries` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;